:root {
  --bg: #1b1b2f;
  --card: #f4f4f8;
  --ink: #1b1b2f;
  --accent: #ff6b6b;
  --accent-dark: #d94f4f;
  --muted: #6b6b83;
  --focus: #ffd166;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,.04) 25%, transparent 25%, transparent 75%, rgba(255,255,255,.04) 75%),
    linear-gradient(45deg, rgba(255,255,255,.04) 25%, transparent 25%, transparent 75%, rgba(255,255,255,.04) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  padding: 28px 24px;
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--accent-dark);
}

h1 {
  margin: 0 0 20px;
  font-size: 1.5rem;
  letter-spacing: .5px;
}

.field { margin-bottom: 18px; border: 0; padding: 0; }

label, legend {
  display: block;
  font-weight: 700;
  margin-bottom: 8px;
  font-size: 1rem;
}

input {
  width: 100%;
  padding: 12px;
  font: inherit;
  font-size: 1.1rem;
  border: 3px solid var(--ink);
  background: #fff;
  color: var(--ink);
}

input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-group {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1 1 0;
  min-width: 72px;
  padding: 12px 8px;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: #fff;
  border: 3px solid var(--ink);
  cursor: pointer;
  transition: transform .06s ease, background .12s ease;
}

.tip-btn:hover { background: #ffe3e3; }

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active { transform: translate(2px, 2px); }

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
  box-shadow: inset 0 0 0 3px var(--ink);
}

.error {
  margin: 0 0 14px;
  color: var(--accent-dark);
  font-weight: 700;
}

.results {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 4px dashed var(--ink);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 8px 0;
}

.result-row span { color: var(--muted); font-weight: 600; }
.result-row strong { font-size: 1.35rem; }

@media (max-width: 380px) {
  body { padding: 12px; }
  .card { padding: 20px 16px; }
  h1 { font-size: 1.3rem; }
}

(function () {
  "use strict";

  const billInput = document.getElementById("bill");
  const peopleInput = document.getElementById("people");
  const tipButtons = Array.from(document.querySelectorAll(".tip-btn"));
  const tipOut = document.getElementById("tip-per-person");
  const totalOut = document.getElementById("total-per-person");
  const errorEl = document.getElementById("error");

  let tipPercent = 15;

  function money(value) {
    return "$" + value.toFixed(2);
  }

  function showError(message) {
    if (message) {
      errorEl.textContent = message;
      errorEl.hidden = false;
    } else {
      errorEl.textContent = "";
      errorEl.hidden = true;
    }
  }

  function update() {
    const bill = parseFloat(billInput.value);
    let people = parseInt(peopleInput.value, 10);

    if (billInput.value.trim() === "" || isNaN(bill) || bill < 0) {
      showError("Enter a valid bill amount of 0 or more.");
      tipOut.textContent = money(0);
      totalOut.textContent = money(0);
      return;
    }

    if (isNaN(people) || people < 1) {
      people = 1;
      peopleInput.value = "1";
    }

    showError("");

    const tipTotal = bill * (tipPercent / 100);
    const tipPerPerson = tipTotal / people;
    const totalPerPerson = (bill + tipTotal) / people;

    tipOut.textContent = money(tipPerPerson);
    totalOut.textContent = money(totalPerPerson);
  }

  function selectTip(button) {
    tipPercent = Number(button.dataset.tip);
    tipButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", btn === button ? "true" : "false");
    });
    update();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      selectTip(button);
    });
  });

  billInput.addEventListener("input", update);
  peopleInput.addEventListener("input", update);

  update();
})();
